def transform_v2(grid):
    h,w=len(grid),len(grid[0])
    walls=[(i,j) for i in range(h) for j in range(w) if grid[i][j]==1]
    # 8-connected wall components
    par={p:p for p in walls}
    def find(x):
        while par[x]!=x: par[x]=par[par[x]]; x=par[x]
        return x
    def uni(a,b):
        ra,rb=find(a),find(b)
        if ra!=rb: par[ra]=rb
    ws=set(walls)
    for i,j in walls:
        for di in(-1,0,1):
            for dj in(-1,0,1):
                if (di,dj)!=(0,0) and (i+di,j+dj) in ws: uni((i,j),(i+di,j+dj))
    comps={}
    for p in walls: comps.setdefault(find(p),[]).append(p)
    # flood zeros 4-conn from border
    reach=set()
    dq=deque((i,j) for i in range(h) for j in range(w) if grid[i][j]==0 and (i in(0,h-1) or j in(0,w-1)))
    seen={p for p in dq}
    while dq:
        i,j=dq.popleft(); reach.add((i,j))
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<h and 0<=b<w and grid[a][b]==0 and (a,b) not in seen:
                seen.add((a,b)); dq.append((a,b))
    out=[row[:] for row in grid]
    closed=set()
    for comp in comps.values():
        cs=set(comp)
        if any(grid[a][b]==0 and (a,b) not in reach
               for a in range(h) for b in range(w)
               if any(abs(a-x)<=1 and abs(b-y)<=1 for x,y in comp)):
            closed.add(find(comp[0]))
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=0: continue
            adjc=any((i+di,j+dj) in cs for di in(-1,0,1) for dj in(-1,0,1)
                     for cs in [set(c) for c in [comps[k] for k in closed]] ) if closed else False
            # simpler: recompute
            adjc=any(grid[i+di][j+dj]==1 and find((i+di,j+dj)) in closed
                     for di in(-1,0,1) for dj in(-1,0,1)
                     if 0<=i+di<h and 0<=j+dj<w)
            if adjc:
                has=any(0<=i+di<h and 0<=j+dj<w and grid[i+di][j+dj]==1 for di in(-1,0,1) for dj in(-1,0,1))
                out[i][j]=3 if has else 0
    return out

