                for dj in(-1,0,1):
                    q_=(a+di,b+dj)
                    if q_ in walls and q_ not in seen: seen.add(q_); st.append(q_)
        comps.append(comp)
    reach=set(); dq=deque((i,j) for i in range(h) for j in range(w) if d[i][j]==0 and (i in(0,h-1) or j in(0,w-1)))
    while dq:
        i,j=dq.popleft()
        if (i,j) in reach: continue
        reach.add((i,j))
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<h and 0<=b<w and d[a][b]==0: dq.append((a,b))
    closed=[]
    for c in comps:
        if any(d[a][b]==0 and (a,b) not in reach and any(abs(a-x)<=1 and abs(b-y)<=1 for x,y in c)
               for a in range(h) for b in range(w)):
            closed.append(c)
    def w8(i,j):
        return [(a,b) for a in range(i-1,i+2) for b in range(j-1,j+2) if (a,b)!=(i,j) and 0<=a<h and 0<=b<w and d[a][b]==1]
    twos=set()
    for c in closed:
        rs=[x for x,y in c]; cs=[y for x,y in c]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        for x,y in c:
            for di in(-1,0,1):
                for dj in(-1,0,1):
                    a,b=x+di,y+dj
                    if 0<=a<h and 0<=b<w and d[a][b]==0 and (a,b) in reach: twos.add((a,b))
        # pocket-at-bbox-corner external diagonals
        for (cr,cc,dr,dc) in ((r0,c0,-1,-1),(r0,c1,-1,1),(r1,c0,1,-1),(r1,c1,1,1)):
            p=(cr,cc)
            if d[cr][cc]!=0: continue
            # 3-wall pocket: the two edge-adjacent in-bbox directions and the diagonal inward are walls
            ew=(cr+dr*-1, cc+dc*-1)   # step inward along row edge
            ew2=(cr, cc+(-dc if False else (1 if dc==-1 else -1)))
            # orientation: for top-left corner (dr=-1,dc=-1): edges are (r0,c0+1) east and (r0+1,c0) south, diag (r0+1,c0+1)
            esign=1 if cc==c0 else -1  # horizontal inward
            ssign=1 if cr==r0 else -1  # vertical inward
            e_=(cr, cc+esign); s_=(cr+ssign, cc); dg=(cr+ssign, cc+esign)
            if e_ in walls and s_ in walls and dg in walls:
                ext=(cr+dr, cc+dc)
                if 0<=ext[0]<h and 0<=ext[1]<w and d[ext[0]][ext[1]]==0 and ext in reach:
                    twos.add(ext)
    out=[]
    for i in range(h):
        row_=[]
        for j in range(w):
            if d[i][j]==1: row_.append(1)
            elif (i,j) in twos: row_.append(2)
            elif (i,j) not in reach and len(w8(i,j))>=1: row_.append(3)
            else: row_.append(0)
        out.append(row_)
    e=[[o[i][j] for j in range(w)] for i in range(len(o))]
    diff=[(i,j,out[i][j],e[i][j]) for i in range(min(h,len(e))) for j in range(w) if out[i][j]!=e[i][j]]
    return out, diff
