from collections import deque
def base(d):
    H_,W_=len(d),len(d[0])
    lab=[[-1]*W_ for _ in range(H_)]
    cid=0
    for i in range(H_):
        for j in range(W_):
            if d[i][j]==1 and lab[i][j]<0:
                dq_=deque([(i,j)]); lab[i][j]=cid
                while dq_:
                    a,b=dq_.popleft()
                    for di in(-1,0,1):
                        for dj in(-1,0,1):
                            x,y=a+di,b+dj
                            if 0<=x<H_ and 0<=y<W_ and d[x][y]==1 and lab[x][y]<0:
                                lab[x][y]=cid; dq_.append((x,y))
                cid+=1
    # border 4-reachability of zeros
    reach=[[False]*W_ for _ in range(H_)]
    dq_=deque()
    for i in range(H_):
        for j in (0,W_-1):
            if d[i][j]==0 and not reach[i][j]: reach[i][j]=True; dq_.append((i,j))
    for j in range(W_):
        for i in (0,H_-1):
            if d[i][j]==0 and not reach[i][j]: reach[i][j]=True; dq_.append((i,j))
    while dq_:
        a,b=dq_.popleft()
        for di,dj in((-1,0),(1,0),(0,-1),(0,1)):
            x,y=a+di,b+dj
            if 0<=x<H_ and 0<=y<W_ and d[x][y]==0 and not reach[x][y]:
                reach[x][y]=True; dq_.append((x,y))
    closed=[False]*cid
    for i in range(H_):
        for j in range(W_):
            if d[i][j]==1:
                for di in(-1,0,1):
                    for dj in(-1,0,1):
                        x,y=i+di,j+dj
                        if 0<=x<H_ and 0<=y<W_ and d[x][y]==0 and not reach[x][y]:
                            closed[lab[i][j]]=True
    w8=[[0]*W_ for _ in range(H_)]
    for i in range(H_):
        for j in range(W_):
            if d[i][j]==0:
                w8[i][j]=sum(1 for di in(-1,0,1) for dj in(-1,0,1) if 0<=i+di<H_ and 0<=j+dj<W_ and d[i+di][j+dj]==1)
    out=[[0]*W_ for _ in range(H_)]
    for i in range(H_):
        for j in range(W_):
            if d[i][j]==1: out[i][j]=1; continue
            if not reach[i][j]:
                out[i][j]= 3 if (w8[i][j]>=1 and any(closed[lab[i+di][j+dj]] for di in(-1,0,1) for dj in(-1,0,1) if 0<=i+di<H_ and 0<=j+dj<W_ and d[i+di][j+dj]==1)) else 0
            else:
                adj_closed=any(closed[lab[i+di][j+dj]] for di in(-1,0,1) for dj in(-1,0,1) if 0<=i+di<H_ and 0<=j+dj<W_ and d[i+di][j+dj]==1)
                if adj_closed and w8[i][j]>=1: out[i][j]=2
    return out, reach, closed, lab, w8

def concave(d, out, reach, closed, lab, w8, minn=2):
    H_,W_=len(d),len(d[0])
    res_=[row[:] for row in out]
    for i in range(H_):
        for j in range(W_):
            if d[i][j]==0 and reach[i][j] and out[i][j]==0:
                n4=0
                for di,dj in((-1,0),(1,0),(0,-1),(0,1)):
                    x,y=i+di,j+dj
                    if 0<=x<H_ and 0<=y<W_ and out[x][y]==2: n4+=1
                if n4>=minn: res_[i][j]=2
    return res_

